export * from './testSuite';
import { getAgent } from '@finos/fdc3';
import { getPackMembers, getPackNames, executeTestsInBrowser, executeManualTestsInBrowser, allTests, allManualTests, } from './testSuite';
import { ProgressReporter } from './progressReporter';
import { attachSignals, signalError } from './headlessSignal';
// eslint-disable-next-line @typescript-eslint/no-require-imports
require('mocha/mocha.css');
// eslint-disable-next-line @typescript-eslint/no-require-imports
require('source-map-support/browser-source-map-support.js');
mocha.setup('bdd');
mocha.reporter(ProgressReporter);
const testSuite = document.getElementById('testSuite');
// populate drop-down
getPackNames().forEach(pn => {
    const optGroup = document.createElement('optgroup');
    optGroup.setAttribute('label', pn);
    getPackMembers(pn).forEach(pm => {
        const opt = document.createElement('option');
        const text = document.createTextNode(pm);
        opt.setAttribute('value', pm);
        opt.appendChild(text);
        optGroup.appendChild(opt);
    });
    testSuite.appendChild(optGroup);
});
function executeTests() {
    toggleVersionSelector();
    toggleBackButton();
    const testSuiteMenu = document.getElementById('testSuite');
    const selectedSuite = testSuiteMenu.options[testSuiteMenu.selectedIndex].innerHTML;
    const action = () => executeTestsInBrowser(selectedSuite);
    if (window.fdc3) {
        action();
    }
    else {
        getAgent().then(() => action());
    }
}
function executeManualTests() {
    toggleVersionSelector();
    toggleBackButton();
    const manualTests = document.getElementById('manualTests');
    const selectedManualTest = manualTests.options[manualTests.selectedIndex].innerHTML;
    console.log('******** Selected manual test is', selectedManualTest);
    const action = () => executeManualTestsInBrowser(selectedManualTest);
    if (window.fdc3) {
        action();
    }
    else {
        getAgent().then(() => action());
    }
}
function returnToTestSelection() {
    location.reload();
}
function toggleVersionSelector() {
    const versionSelector = document.getElementById('version-selector');
    const manualSelector = document.getElementById('manualTests-selector');
    if (versionSelector.style.display === 'none') {
        versionSelector.style.display = 'block';
        manualSelector.style.display = 'block';
    }
    else {
        versionSelector.style.display = 'none';
        manualSelector.style.display = 'none';
    }
}
function toggleBackButton() {
    const backButton = document.getElementById('back-button');
    if (window.getComputedStyle(backButton).display === 'none') {
        backButton.style.display = 'block';
    }
    else {
        backButton.style.display = 'none';
    }
}
document.getElementById('runButton').addEventListener('click', executeTests);
document.getElementById('back-button').addEventListener('click', returnToTestSelection);
document.getElementById('manualTestsRunButton').addEventListener('click', executeManualTests);
/**
 * Headless mode. Launching this app with `?suite=<pack>` (or `?manual=<test>`)
 * runs the tests unattended and reports the outcome via ./headlessSignal.
 * Without those parameters nothing below has any effect and the app behaves
 * exactly as it always has.
 *
 * Supported parameters:
 *   suite=<pack>        one of the packs in the "Test suite" drop-down, e.g. "All"
 *   manual=<test>       one of the manual tests; needs a human at the intent resolver
 *   delay=<ms>          wait this long after the agent is ready before starting
 *   agentTimeout=<ms>   fail with status "error" if getAgent() takes longer (default 30000)
 *
 * Any bad parameter, and any failure while starting up, reports a terminal
 * "error" result rather than leaving the run hanging.
 */
function headlessBootstrap() {
    const params = new URLSearchParams(window.location.search);
    const suite = params.get('suite');
    const manual = params.get('manual');
    if (!suite && !manual) {
        getAgent(); // ensure the agent is ready before running tests
        return;
    }
    const name = (suite ?? manual);
    const known = suite ? allTests[name] : allManualTests[name];
    if (!known) {
        const available = Object.keys(suite ? allTests : allManualTests).join(', ');
        signalError(name, new Error(`Unknown ${suite ? 'suite' : 'manual test'} "${name}". Available: ${available}`));
        return;
    }
    const delay = numericParam(params, 'delay', 0);
    const agentTimeout = numericParam(params, 'agentTimeout', 30000);
    if (delay === undefined || agentTimeout === undefined) {
        signalError(name, new Error('delay and agentTimeout must be non-negative numbers of milliseconds'));
        return;
    }
    // Held here rather than in the .then() closure so that the .catch() below can
    // still reach the agent, and so report an error over FDC3 as well as the
    // other three channels.
    let agent;
    // Everything from here on has to reach signalError if it throws: a headless
    // run that dies without emitting a terminal result is a silent CI hang, which
    // is the exact failure this feature exists to prevent.
    (async () => {
        // hide the interactive chrome so screenshots show the results and nothing else
        document.getElementById('version-selector').style.display = 'none';
        document.getElementById('manualTests-selector').style.display = 'none';
        document.getElementById('back-button').style.display = 'none';
        document.body.dataset.conformance = 'starting';
        let timer;
        const timeout = new Promise((_, reject) => {
            timer = setTimeout(() => reject(new Error(`getAgent() did not resolve within ${agentTimeout}ms`)), agentTimeout);
        });
        try {
            agent = await Promise.race([getAgent(), timeout]);
        }
        finally {
            clearTimeout(timer);
        }
        if (delay > 0) {
            await new Promise(resolve => setTimeout(resolve, delay));
        }
        const run = suite ? executeTestsInBrowser : executeManualTestsInBrowser;
        await run(name, runner => attachSignals(runner, name, agent));
    })().catch(ex => signalError(name, ex, agent));
}
/**
 * Reads a non-negative numeric query parameter. Returns the fallback when the
 * parameter is absent, or `undefined` when it is present but not a usable
 * number, so the caller can report it rather than passing nonsense to
 * setTimeout: `Number('abc')` is NaN, which setTimeout clamps to 0, and
 * `Number('')` is 0, which would silently turn `?agentTimeout=` into an
 * instant failure.
 */
function numericParam(params, key, fallback) {
    const raw = params.get(key);
    if (raw === null) {
        return fallback;
    }
    if (raw.trim() === '') {
        return undefined;
    }
    const value = Number(raw);
    return Number.isFinite(value) && value >= 0 ? value : undefined;
}
headlessBootstrap();
