/**
 * Headless-mode signalling for the conformance suite.
 *
 * When the conformance app is launched with a `?suite=` query parameter it runs
 * unattended and announces its progress and final result on four independent
 * channels, so that whatever is driving the run - Playwright, the desktop agent
 * hosting the iframe, or another FDC3 app - can tell when it has finished.
 *
 *  1. `window.__FDC3_CONFORMANCE__` plus a `data-conformance` attribute on
 *     `<body>`. For same-origin browser automation (`page.waitForFunction`).
 *  2. A `console.log` sentinel line. Survives cross-origin iframes and can be
 *     scraped straight out of CI logs.
 *  3. `postMessage` to `window.parent` and `window.opener`. For a desktop agent
 *     hosting this app in an iframe or popup.
 *  4. An FDC3 broadcast on a dedicated app channel. For a collector app
 *     registered in the desktop agent's app directory.
 *
 * None of this runs unless headless mode is requested, so the interactive UI is
 * completely unaffected.
 */
/** Prefix of the single-line console message carrying the final result. */
export const RESULT_SENTINEL = 'FDC3_CONFORMANCE_RESULT';
/** Prefix of the per-test console progress messages. */
export const STATUS_SENTINEL = 'FDC3_CONFORMANCE_STATUS';
/** App channel the final result is broadcast on. */
export const RESULT_CHANNEL_ID = 'fdc3-conformance-results';
/** Context type of the broadcast result. */
export const RESULT_CONTEXT_TYPE = 'fdc3.conformance.result';
/** Maximum number of characters of stack trace retained per failing test. */
const MAX_STACK_CHARS = 2000;
function truncate(value, max) {
    if (!value) {
        return undefined;
    }
    return value.length > max ? `${value.slice(0, max)}\n... (truncated)` : value;
}
/**
 * Publishes the state on every channel. Terminal states (`complete` and
 * `error`) additionally go out over postMessage and FDC3; `running` updates
 * stay on the cheap local channels so that a long run does not spam the
 * desktop agent.
 */
async function publish(state, agent) {
    // 1. global + DOM flag
    window.__FDC3_CONFORMANCE__ = state;
    if (document.body) {
        document.body.dataset.conformance = state.status;
    }
    const terminal = state.status !== 'running';
    // 2. console sentinel
    const sentinel = terminal ? RESULT_SENTINEL : STATUS_SENTINEL;
    try {
        console.log(`${sentinel} ${JSON.stringify(state)}`);
    }
    catch (ex) {
        console.log(`${sentinel} {"status":"error","error":"result was not serialisable: ${String(ex)}"}`);
    }
    if (!terminal) {
        return;
    }
    // 3. postMessage to whoever is hosting this app
    const message = { type: RESULT_SENTINEL, result: state };
    try {
        if (window.parent && window.parent !== window) {
            window.parent.postMessage(message, '*');
        }
        if (window.opener) {
            window.opener.postMessage(message, '*');
        }
    }
    catch (ex) {
        console.warn(`${RESULT_SENTINEL} postMessage failed`, ex);
    }
    // 4. FDC3 broadcast, for a collector app in the app directory
    if (agent) {
        try {
            const channel = await agent.getOrCreateChannel(RESULT_CHANNEL_ID);
            await channel.broadcast({
                type: RESULT_CONTEXT_TYPE,
                name: `FDC3 conformance: ${state.suite}`,
                result: state,
                // eslint-disable-next-line @typescript-eslint/no-explicit-any
            });
        }
        catch (ex) {
            console.warn(`${RESULT_SENTINEL} broadcast failed`, ex);
        }
    }
}
/**
 * Reports a failure that happened before (or instead of) a test run - most
 * commonly `getAgent()` never resolving, or an unknown suite name.
 */
export function signalError(suite, error, agent) {
    const err = error instanceof Error ? error : new Error(String(error));
    void publish({
        status: 'error',
        suite,
        error: err.message,
        stack: truncate(err.stack, MAX_STACK_CHARS),
    }, agent);
}
/**
 * Attaches the signal emitters to a Mocha runner. Must be called synchronously
 * in the same tick as `mocha.run()` so that no events are missed.
 */
export function attachSignals(runner, suite, agent) {
    const tests = [];
    const startedAtMs = Date.now();
    const startedAt = new Date(startedAtMs).toISOString();
    const record = (test, state, err) => {
        tests.push({
            title: test.fullTitle(),
            suite: test.parent?.title ?? '',
            state,
            durationMs: test.duration,
            error: err?.message,
            stack: truncate(err?.stack, MAX_STACK_CHARS),
        });
        void publish({
            status: 'running',
            suite,
            completed: tests.length,
            total: runner.total,
        });
    };
    runner.on('pass', test => record(test, 'passed'));
    runner.on('fail', (test, err) => record(test, 'failed', err));
    runner.on('pending', test => record(test, 'pending'));
    runner.on('end', () => {
        const finishedAtMs = Date.now();
        const stats = runner.stats ?? { passes: 0, failures: 0, pending: 0 };
        void publish({
            status: 'complete',
            suite,
            passes: stats.passes,
            failures: stats.failures,
            pending: stats.pending,
            total: runner.total,
            durationMs: finishedAtMs - startedAtMs,
            startedAt,
            finishedAt: new Date(finishedAtMs).toISOString(),
            userAgent: navigator.userAgent,
            tests,
        }, agent);
    });
}
